'use strict';
const $ = (q) => document.querySelector(q);
const h = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm = (s) => String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const modeNames = {ckd:'Non-dialysis',ihd:'IHD',crrt:'CRRT',pd:'PD',sled:'PIRRT/SLED'};
const modeTitles = {ckd:'Renal dose adjustment',ihd:'Intermittent haemodialysis',crrt:'Continuous kidney replacement therapy',pd:'Peritoneal dialysis',sled:'Prolonged intermittent therapy / SLED'};
const flagNames = {adjust:'Renal adjustment',no_adjust:'No routine renal adjustment',monitor:'Additional review',caution:'Check eligibility / source',catalog:'Catalog only · no renal guidance'};
const statusNames = {not_curated:'Not yet curated',insufficient_data:'Insufficient data in cited source',specialist:'Specialist review required',avoid:'Do not use in this setting',not_indicated:'Not indicated in the selected source'};
let db, sourceMap, drugMap, renderKey=null, visible=[], selected=null, mode='ckd', category='all', view='all', favourites=new Set(), toastTimer, listLimit=60;
try { const saved=JSON.parse(localStorage.getItem('renalrounds-favourites')||'[]'); if(Array.isArray(saved)) favourites=new Set(saved.filter(x=>typeof x==='string')); } catch {}
function storageSet(key,value) {try{localStorage.setItem(key,value);return true;}catch{return false;}}
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3000);}
function setHash(){const next=`#drug=${encodeURIComponent(selected||'')}&mode=${mode}`;try{history.replaceState(null,'',next);}catch{if(location.hash!==next)location.hash=next;}}
function sourceDate(value){return value?new Date(value+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}):'Not checked';}
function sourceLink(id){const s=sourceMap.get(id);return s?`<a href="${h(s.url)}" target="_blank" rel="noopener noreferrer">${h(s.title)} ↗</a>`:'';}
function filterDrugs(query, group, savedOnly){const term=norm(query),tokens=term.split(' ').filter(Boolean),setting=$('#setting-filter').value,route=$('#route-filter').value,content=$('#content-filter').value,otc=$('#otc-filter').checked;return db.drugs.filter(d=>(group==='all'||d.category===group)&&(setting==='all'||d.modalities[setting].status==='summarized')&&(!savedOnly||favourites.has(d.id))&&(view!=='new'||d.addedInVersion===latestClinicalVersion()||d.updatedInVersion===latestClinicalVersion())&&(route==='all'||d.routes.includes(route))&&(content==='all'||(content==='pk'?d.pharmacokinetics.status==='source_summary':d.entryType===content))&&(!otc||d.otc)&&tokens.every(t=>d.searchText.includes(t))).sort((a,b)=>{const score=d=>d.nameKeys[0]===term?3:d.nameKeys.slice(1).includes(term)?2:d.nameKeys[0].startsWith(term)?1:0;return term?score(b)-score(a):0;});}
function renderResults(){
  visible=filterDrugs($('#search').value,category,view==='saved');
  $('#clear-search').hidden=!$('#search').value;const active=[$('#setting-filter').value!=='all'?modeNames[$('#setting-filter').value]+' summary':'',$('#route-filter').value!=='all'?$('#route-filter').value:'',$('#content-filter').value!=='all'?$('#content-filter').selectedOptions[0].textContent:'',$('#otc-filter').checked?'OTC':'',category!=='all'?category:'',view==='new'?'Latest clinical additions':view==='saved'?'Favourites':''].filter(Boolean);$('#active-filters').textContent=active.join(' · ')||'All medicines';$('#clear-filters').disabled=!active.length;
  $('#result-count').textContent=visible.length;
  $('#list-heading').textContent=view==='saved'?'FAVOURITES':view==='new'?'LATEST CLINICAL ADDITIONS':category==='all'?'ALL MEDICINES':category.toUpperCase();
  $('#saved-count').textContent=favourites.size;
  $('#all-count').textContent=db.drugs.length;
  document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view&&category==='all'));
  document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));
  $('#mobile-category').value=view==='saved'?'saved':view==='new'?'new':category;
  if(!visible.some(d=>d.id===selected)) selected=norm($('#search').value)?visible[0]?.id||null:null;
  const selectedIndex=visible.findIndex(d=>d.id===selected);if(selectedIndex>=listLimit)listLimit=Math.ceil((selectedIndex+1)/60)*60;
  $('#more-results').hidden=visible.length<=listLimit;
  $('#more-results').textContent=`Show next ${Math.min(60,Math.max(0,visible.length-listLimit))} · ${Math.min(visible.length,listLimit)} of ${visible.length} shown`;
  const searchTerm=norm($('#search').value),outside=searchTerm?db.drugs.filter(d=>(d.nameKeys.includes(searchTerm))&&!visible.some(v=>v.id===d.id)):[];$('#filter-matches').hidden=!outside.length;$('#filter-matches').innerHTML=outside.length?`<strong>${outside.length} exact name match${outside.length>1?'es':''} hidden by filters.</strong> <button id="show-filtered-match">Show matching medicine${outside.length>1?'s':''}</button>`:'';
  $('#results').innerHTML=visible.length?visible.slice(0,listLimit).map(d=>`<div class="result"><button class="result-button ${d.id===selected?'selected':''}" data-drug="${h(d.id)}" aria-current="${d.id===selected?'true':'false'}"><span class="result-initial">${h(d.name.slice(0,2))}</span><span class="result-text"><span class="result-title">${h(d.name)}</span><span class="result-class">${h(d.drugClass)} · ${h(d.routes.join(' / '))}</span><span class="result-tag ${h(d.flag)}">${h(d.entryType==='safety'?'Safety note · no renal dose':d.entryType==='catalog'&&d.pharmacokinetics.status==='source_summary'?'PK available · doses pending':flagNames[d.flag])}</span></span><span class="row-arrow" aria-hidden="true">›</span></button></div>`).join(''):
   `<div class="empty-result"><strong>${view==='saved'?'No saved matches':'No matching entry'}</strong>${renderSuggestions()}<p>Check the spelling and active filters. An absent result does not establish renal safety.</p><button id="reset-filters">Clear search and filters</button>${$('#search').value?`<br><a href="https://dailymed.nlm.nih.gov/dailymed/search.cfm?query=${encodeURIComponent($('#search').value)}" target="_blank" rel="noopener noreferrer">Search this term on DailyMed ↗</a>`:''}</div>`;
  renderMonograph();
}
function renderMonograph(){
  const nextKey=JSON.stringify([selected,mode,favourites.has(selected)]);if(nextKey===renderKey)return;renderKey=nextKey;
  $('#selected-shortcut').hidden=true;
  if(!selected){$('#monograph').innerHTML='<div class="no-selection"><div class="eyebrow" style="justify-content:center">NO MONOGRAPH SELECTED</div><h2>Select a medicine.</h2><p>Search above or choose a result to view its renal guidance.</p></div>';setHash();return;}
  const d=drugMap.get(selected), m=d.modalities[mode], saved=favourites.has(d.id);
  if(d.entryType!=='renal'){renderInventoryEntry(d,saved);attachDrugTools();setHash();return;}
  const ucsf=d.sourceIds.some(id=>sourceMap.get(id)?.title.startsWith('UCSF'));
  const metric=m.settingMeasure||(mode==='ckd'?d.kidneyMetric:mode==='ihd'?(ucsf?'High-flux IHD for UCSF regimens':'Intermittent haemodialysis'):mode==='crrt'?(ucsf?'UCSF regimens: CVVHD, 2 L/h, residual GFR <10 mL/min':'Confirm the specific CRRT modality and delivered prescription'):mode==='pd'?'CAPD and APD are not interchangeable':'Confirm modality, duration and flow settings');
  const assumption=mode==='sled'&&m.status==='summarized'?'<div class="context-notice"><strong>Match the PIRRT prescription.</strong> Session duration, flow, residual function and dose timing are part of this recommendation. PIRRT and SLED prescriptions vary; this is not a universal conversion from CRRT or IHD.</div>':(mode==='crrt'&&ucsf)?'<div class="context-notice"><strong>Match the prescription.</strong> UCSF continuous-HD tables assume CVVHD at 2 L/h and residual native GFR &lt;10 mL/min. Flow changes, interruptions and other modalities need individual review. These are not universal CRRT doses.</div>':(mode==='ihd'&&ucsf)?'<div class="context-notice"><strong>Dialysis timing.</strong> UCSF regimens assume high-flux HD. “Every evening” means a daily evening regimen, not only dialysis days. “After HD” means after each scheduled session. Confirm the complete schedule.</div>':'';
  const tables=m.tables.map((t,i)=>`<div class="dose-table-wrap"><h4 class="indication-title"><span class="num">${String(i+1).padStart(2,'0')}</span>${h(t.indication)}</h4><table class="dose-table"><thead><tr><th scope="col">${mode==='ckd'?'Kidney function / context':'Treatment context'}</th><th scope="col">${d.id==='allopurinol'&&mode==='ckd'?'Initial dose only':d.id==='gabapentin'&&mode==='ckd'?'Total daily range · not starting dose':'Source dosing summary'}</th></tr></thead><tbody>${t.rows.map(r=>`<tr><td>${h(r.context)}</td><td>${h(r.dose)}</td></tr>`).join('')}</tbody></table></div>`).join('');
  const gap=m.status!=='summarized'?`<div class="gap-state ${m.status==='avoid'?'danger':''}"><span class="gap-icon" aria-hidden="true">${m.status==='avoid'?'!':'i'}</span><h4>${h(statusNames[m.status]||'Review required')}</h4><p>${h(m.notes||'A modality-specific recommendation has not been curated for this drug. This is a coverage gap, not evidence of safety or a recommendation to avoid. Use a current specialist source and local renal-pharmacy guidance.')}</p></div>`:'';
  const refs=m.sourceIds.length?m.sourceIds:d.sourceIds;
  $('#monograph').innerHTML=`<div class="mono-head"><div class="mono-overline"><span>${h(d.category.toUpperCase())} / ${h(d.drugClass.toUpperCase())}</span><button class="save-button ${saved?'saved':''}" id="save-drug" aria-label="${saved?'Remove from':'Add to'} favourites" aria-pressed="${saved}"><span aria-hidden="true">${saved?'★':'☆'}</span> ${saved?'Saved':'Save'}</button></div><h2>${h(d.name)}</h2><div class="mono-sub">${h(d.aliases.join(' · '))}<span>•</span>${h(d.formulation)}</div><p class="mono-summary">${h(d.summary)}</p>${d.marketStatus?`<div class="context-notice source-warning">${h(d.marketStatus)}</div>`:''}</div>
    <div class="mode-tabs" role="tablist" aria-label="Kidney treatment setting">${Object.entries(modeNames).map(([key,label])=>`<button role="tab" id="tab-${key}" class="mode-tab ${mode===key?'active':''}" data-mode="${key}" aria-selected="${mode===key}" aria-controls="dose-panel" tabindex="${mode===key?'0':'-1'}">${label}${d.modalities[key].status!=='summarized'?'<span class="gap-dot" title="Incomplete or specialist guidance" aria-label="Incomplete or specialist guidance"></span>':''}</button>`).join('')}</div>
    <div class="dose-content" id="dose-panel" role="tabpanel" aria-labelledby="tab-${mode}" tabindex="0"><div class="dose-title-row"><h3>${modeTitles[mode]}</h3><span class="mode-label">${mode==='ckd'?'INDICATION SPECIFIC':mode==='sled'?'PIRRT/SLED':mode.toUpperCase()}</span></div><div class="metric-strip"><b>${mode==='ckd'?'FUNCTION MEASURE':'TREATMENT SETTING'}</b><span>${h(metric)}</span></div>${d.updateNote?`<div class="context-notice"><strong>Label update.</strong> ${h(d.updateNote)}</div>`:''}${assumption}${(d.evidenceNotes||[]).map(n=>`<div class="context-notice source-warning"><strong>${h(n.title)}.</strong> ${h(n.text)}<div>${n.sourceIds.map(sourceLink).join(" · ")}</div></div>`).join("")}${m.status==='avoid'?gap:''}${tables}${m.status==='summarized'&&m.notes?`<div class="context-notice ${m.notes.includes('DIFFERENT')||m.notes.includes('differs')?'source-warning':''}"><strong>Source note.</strong> ${h(m.notes)}</div>`:''}
    ${d.considerations&&d.considerations!==m.notes?`<div class="dose-note"><strong>Clinical considerations.</strong> ${h(d.considerations)}</div>`:''}${m.status!=='avoid'?gap:''}
    ${mode==='ckd'?'<p class="boundary-note">Use the measure and units stated above. Source bands may have gaps or overlaps at exact cutoffs; verify the original table at those boundaries. CKD stage alone does not select a dose.</p>':''}
    <div class="source-inline"><span>SOURCE</span>${refs.map(sourceLink).join('<span>·</span>')}</div></div>
    <div class="mono-bottom"><div class="mono-badges review-status"><span class="pill pending">CLINICAL APPROVAL PENDING</span></div><details class="info-detail"><summary>Evidence & review record</summary><div class="reference-status"><strong>Reference comparison</strong><p>BNF 92: monograph comparison pending — content inaccessible. ${d.referenceChecks?.pdr?.status==='accessed'?'PDR: linked digital monograph consulted.':d.referenceChecks?.pdr?.status==='update_bulletin_checked'?'PDR: October 2026 update bulletin checked against the US label.':'PDR: no drug-specific comparison completed for this entry.'}</p><p>${h(d.jurisdiction)}</p></div>${d.sourceIds.map(id=>{const s=sourceMap.get(id);return `<div class="source-card"><div class="source-type">${h(s.type.toUpperCase())}</div><a href="${h(s.url)}" target="_blank" rel="noopener noreferrer">${h(s.title)} ↗</a><small>${h(s.section)}<br>Source checked: ${h(sourceDate(s.accessed))} · Independent clinical review: pending</small></div>`;}).join('')}<p>These are condensed source summaries. Institutional guidance and US labels can differ. No independent clinician has approved this entry; review date and source-access date are distinct.</p></details><details class="info-detail"><summary>Scope, missing data & abbreviations</summary><p>${h(d.completeness)}</p><p>Missing modality data must not be replaced by the non-dialysis dose. PD does not cover intraperitoneal peritonitis therapy unless expressly stated. SLED, paediatrics, pregnancy and changing kidney function require separate protocols. CVVH/CVVHDF are covered only when explicitly stated in the selected source.</p><p>PO: oral · IV: intravenous · SC: subcutaneous · HD: haemodialysis · IHD: intermittent HD · CRRT: continuous renal replacement therapy · CVVHD: continuous venovenous HD · CAPD/APD: continuous ambulatory/automated PD · PIRRT: prolonged intermittent renal replacement therapy · SLED: sustained low-efficiency dialysis · CrCl: creatinine clearance · GFR/eGFR: (estimated) glomerular filtration rate · CAP: community-acquired pneumonia · NVAF: nonvalvular atrial fibrillation · VTE: venous thromboembolism.</p></details><div class="review-note">DRAFT v${h(db.version)} · Source check ${h(sourceDate(d.review.sourceCheckedAt))} · Independent nephrology + renal-pharmacy review pending.</div></div>`;
  $('#monograph .mono-bottom').insertAdjacentHTML('beforebegin',renderPharmacokinetics(d));
  const shared=sharedSafety(d);if(shared)$('#dose-panel').insertAdjacentHTML('afterbegin',shared);
  attachDrugTools();setHash();
}
function sharedSafety(d){
 const g=db.sharedGuidance[d.sharedGuidanceId];
 return g?`<div class="context-notice safety-note"><strong>${h(g.title)}</strong><p>${h(g.text)}</p><div class="source-inline">${g.sourceIds.map(sourceLink).join(' · ')}</div></div>`:'';
}
function renderInventoryEntry(d,saved){
 const safety=d.entryType==='safety',hasPK=d.pharmacokinetics.status==='source_summary';
 $('#monograph').innerHTML=`<div class="mono-head"><div class="mono-overline"><span>${h(d.category)}</span><button class="save-button ${saved?'saved':''}" id="save-drug" aria-pressed="${saved}" aria-label="${saved?'Remove from':'Add to'} favourites">${saved?'★ Saved':'☆ Save'}</button></div><h2>${h(d.name)}</h2><div class="mono-sub">${h(d.aliases.join(' · '))}</div><p class="mono-summary">${h(d.formulation)}</p></div>${hasPK?renderPharmacokinetics(d):''}<div class="dose-content"><div class="mono-badges"><span class="pill ${safety?'pending':'catalog-pill'}">${safety?'SHARED SAFETY NOTE':hasPK?'PK AVAILABLE · DOSES PENDING':'CATALOG ONLY'}</span><span class="pill pending">NO CURATED RENAL DOSE</span></div><div class="gap-state catalog-gap"><h3>${safety?'Safety information; dosing review pending':'Renal guidance is not yet available'}</h3><p>${h(d.summary)}</p><p>No non-dialysis, IHD, CRRT, PD or SLED prescription is inferred for this entry.</p></div>${sharedSafety(d)}<a class="label-search" href="${h(d.labelSearchUrl)}" target="_blank" rel="noopener noreferrer">Find the current product label on DailyMed ↗</a><p class="boundary-note">This link opens a label search. ${hasPK?'Only the cited PK fields have been checked; a complete renal-dose monograph has not been curated.':'A matching clinical label has not been checked for this catalog entry.'} Check product, route, indication and local authorisation.</p>${!hasPK?renderPharmacokinetics(d):''}<details class="info-detail inventory-detail"><summary>Coverage & review record</summary><p>${h(d.completeness)}</p><p>${safety?'Only the linked shared safety guidance was checked on 29 October 2026. It is not a drug-specific dose monograph.':hasPK?'PK sources are linked in the panel above. The renal-dose source-check date remains blank because a dosing review has not been completed.':'Drug-specific clinical sources have not been reviewed. The source-check date is intentionally blank.'}</p><p>No BNF or PDR monograph comparison has been completed for this entry. Independent nephrology and renal-pharmacist review is pending.</p><p>${h(d.jurisdiction)}</p></details></div>`;
}
function downloadText(name,text,type='text/plain'){
 const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=name;($('#about').open?$('#about'):document.body).append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function exportDatabase(){
 const copy=JSON.parse(JSON.stringify(db));copy.drugs.forEach(d=>{delete d.searchText;delete d.nameKeys;});
 downloadText(`RenalRounds_database_v${db.version}.json`,JSON.stringify(copy,null,2),'application/json');notify('Database export started');
}
function resetFilters(){category='all';view='all';listLimit=60;$('#route-filter').value='all';$('#content-filter').value='all';$('#otc-filter').checked=false;$('#setting-filter').value='all';}
function documentUrl(key){const text=key==='database'?$('#renalrounds-data').textContent:JSON.parse($('#renalrounds-docs').textContent)[key];return URL.createObjectURL(new Blob([text],{type:key==='database'?'application/json':'text/plain'}));}
function renderAbout(){
 const c=db.coverage;
 const counts=Object.keys(modeNames).map(key=>{const n=db.drugs.filter(d=>d.entryType==='renal'&&d.modalities[key].status==='summarized').length;return `<tr><td>${modeNames[key]}</td><td>${n} / ${c.renal} renal profiles</td></tr>`;}).join('');
 $('#about-body').innerHTML=`<div class="modal-callout"><strong>Release ${h(db.version)} · Clinical approval pending.</strong><p>${db.drugs.length} indexed drug/formulation entries: ${c.renal} renal profiles, ${c.safety} shared safety notes, ${c.catalog} catalog-only entries. This is an expanding inventory; it is not a complete or approved prescribing formulary.</p></div><h3>What the three content types mean</h3><p><strong>Renal profiles</strong> contain selected sourced renal adjustment or monitoring summaries, sometimes without a numeric dose. They do not cover every indication, formulation or RRT modality. <strong>Safety notes</strong> link shared kidney-safety guidance and have no curated renal regimen. <strong>Catalog-only entries</strong> make drugs searchable while their renal guidance is being developed; they contain no clinical dose, although a separately sourced PK panel may be available.</p><h3>Kidney-function calculator</h3><p>Open the eGFR calculator beside quick search or in the sidebar. CKD-EPI 2021 creatinine is the default; MDRD is a labelled legacy alternative. Optional body-size adjustment produces non-indexed eGFR, not Cockcroft–Gault CrCl. Values stay in this tab and clear on close. Drug content version ${h(db.clinicalDataVersion||db.version)}; no drug dose is selected automatically.</p><h3>Pharmacokinetic coverage</h3><p>${db.pharmacokineticCoverage.profiles} medicines have source-based PK profiles; ${db.pharmacokineticCoverage.allFourCoreFields} have values for all four core items (reference half-life, Vd, binding and an IHD removal statement). Other fields explicitly distinguish not reported, not yet curated and unknown. Missing parameters are not guessed. Renal-dose curation and PK-source curation are tracked separately.</p><p>${db.drugs.filter(d=>d.pharmacokinetics.historical).length} profiles use the historical Renal Drug Handbook fifth edition, published 2018 (©2019); the source year remains visible. Selected adult Nebraska rows supply new CKD and prescription-specific RRT summaries. Source disagreements remain visible; the uploaded PDFs are not redistributed.</p><p>UKKA 2025 Appendix D supplies selected ESRF half-lives and PD removal categories. Analytes, release formulations and dialysis methods can differ between sources. The app retains those qualifications, including the ramipril/ramiprilat distinction and measured high-flux beta-blocker data. It does not estimate a dialysis supplement from PK parameters.</p><h3>BNF & PDR</h3><p>BNF means British National Formulary, as clarified by the user. BNF 92 (September 2026) remains the intended edition; its publisher listing was checked, but monographs were inaccessible. No entry is BNF-verified. UK SmPCs remain identified as product information.</p><button class="document-download" data-open="references">Open renal reference directory →</button><p>${db.drugs.filter(d=>d.referenceChecks?.pdr?.status==='accessed').length} profiles have a linked PDR digital monograph consulted. PDR is updated continuously. The other renal profiles use the sources listed on each entry; catalog-only records retain a blank renal-dose source-check date; a separate PK check may be present. Source access is distinct from clinical approval.</p><div class="modal-links">${sourceLink('bnf-edition')}${sourceLink('pdr-current')}</div><h3>Selected modality coverage</h3><table class="coverage-table"><thead><tr><th>Setting</th><th>Has selected summary tables</th></tr></thead><tbody>${counts}</tbody></table><p>Not-curated, specialist-review, insufficient-data, avoid and not-indicated statuses are distinct. No RRT regimen is inferred from another setting. UCSF continuous-HD summaries assume CVVHD at 2 L/h and residual native GFR &lt;10 mL/min unless the entry states another source setting.</p><h3>Using the search</h3><p>Type a generic name, selected brand alias, category or curated drug class. Results update immediately; select a result to see findings below. Route, content, category and OTC filters combine. The OTC filter identifies examples available without prescription in some markets; status varies by country, strength and formulation. Catalog route metadata is provisional and does not validate local product availability. “Latest clinical additions” means added to this collection, not newly approved.</p><h3>Kidney-function measures</h3><p>Match the source metric, units, indication and exact threshold. CrCl and indexed eGFR are not interchangeable. CKD stage alone does not choose a dose, and estimates can mislead in AKI. No patient-specific prescription is calculated.</p><div class="modal-links">${sourceLink('kidney-function')}${sourceLink('rrt-assumptions')}</div><h3>Clinical release process</h3><p>Choose the local adult formulary, verify each formulation and indication, reconcile labels with licensed references, complete prescription-specific RRT data, and record independent nephrologist and renal-pharmacist sign-off for every clinical entry. No entry has that sign-off yet. Historical products are marked where known; catalog inclusion does not establish current marketing.</p><h3>Offline & privacy</h3><p>All search data, styling and code are inside index.html. A downloaded copy works in a browser without a server or internet. Source links require internet. Some mobile file managers preview HTML without running JavaScript; use GitHub Pages or a browser that opens local HTML. On HTTPS hosting, sw.js saves a scoped offline copy. The status bar confirms the cached release. Updates wait for the Load available update action; clinical source dates do not change when the app updates. Offline availability depends on browser storage and can be cleared by the browser. Favourites, text size and the manual day/night choice are saved in this browser where local storage is available; otherwise they last for the session. No patient data or analytics are collected.</p><p>Bundled data are static, with no automatic clinical updates. Source-check dates are shown with each entry. Renal-dose sources for catalog records remain unchecked; selected PK-only sources are dated separately.</p><div class="modal-links"><a class="document-download" href="${documentUrl('database')}" download="RenalRounds_database_v${h(db.version)}.json">Download database JSON ↓</a><a class="document-download" href="${documentUrl('guide')}" download="EDITORIAL_GUIDE.md">Download editorial guide ↓</a><a class="document-download" href="${documentUrl('changelog')}" download="CHANGELOG.md">Download changelog ↓</a></div>`;
}

let readerLevel=0;
const readerScales=[1,1.15,1.3,1.5];
function applyTextSize(level){
 readerLevel=Math.max(0,Math.min(readerScales.length-1,Math.round(Number(level)||0)));
 document.documentElement.style.setProperty('--reader-scale',readerScales[readerLevel]);
 document.body.classList.toggle('large-text',readerLevel>0);
 $('#font-reset').textContent=Math.round(readerScales[readerLevel]*100)+'%';
 $('#font-decrease').disabled=readerLevel===0;
 $('#font-toggle').disabled=readerLevel===readerScales.length-1;
 $('#font-toggle').setAttribute('aria-label',readerLevel===readerScales.length-1?'Maximum text size 150%':'Increase text size');
 $('#font-reset').setAttribute('aria-label','Reset text size to 100%, current '+Math.round(readerScales[readerLevel]*100)+'%');
}
function saveTextSize(){storageSet('renalrounds-reader-level',String(readerLevel));}

async function init(){
 try{
  db=JSON.parse($('#renalrounds-data').textContent);
  sourceMap=new Map(db.sources.map(s=>[s.id,s]));drugMap=new Map(db.drugs.map(d=>[d.id,d]));db.drugs.forEach(d=>{d.searchText=norm([d.name,...d.aliases,d.drugClass,d.category,...d.routes].join(' '));d.nameKeys=[d.name,...d.aliases].map(norm);});
  favourites=new Set([...favourites].filter(id=>db.drugs.some(d=>d.id===id)));
  const hash=new URLSearchParams(location.hash.slice(1));if(db.drugs.some(d=>d.id===hash.get('drug')))selected=hash.get('drug');if(Object.hasOwn(modeNames,hash.get('mode')))mode=hash.get('mode');
  const categories=[...new Set(db.drugs.map(d=>d.category))].sort();$('#filter-panel').open=false;
  $('#categories').innerHTML=categories.map(c=>`<button class="side-link category-button" data-category="${h(c)}"><span class="category-dot"></span>${h(c)}<b>${db.drugs.filter(d=>d.category===c).length}</b></button>`).join('');
  $('#mobile-category').insertAdjacentHTML('beforeend','<option value="saved">Favourites</option><option value="new">Latest clinical additions</option>'+categories.map(c=>`<option value="${h(c)}">${h(c)}</option>`).join(''));
  try{const stored=localStorage.getItem('renalrounds-reader-level');applyTextSize(stored===null?(localStorage.getItem('renalrounds-large-text')==='true'?1:0):Number(stored));}catch{applyTextSize(0);}
  $('#total-monographs').textContent=db.drugs.length;$('#coverage-strip').innerHTML=`<span><b>${db.drugs.length}</b> indexed</span><span><b>${db.coverage.renal}</b> renal profiles</span><span><b>${db.coverage.safety}</b> safety notes</span><span><b>${db.coverage.catalog}</b> pending</span>`;$('#new-count').textContent=db.drugs.filter(d=>(d.addedInVersion===latestClinicalVersion()||d.updatedInVersion===latestClinicalVersion())).length;renderAbout();renderResults();
  if((Date.now()-Date.parse(db.releaseDate+'T00:00:00Z'))/86400000>90){document.querySelector('.compact-caption span').textContent='Source recheck overdue · clinical approval pending.';}
 }catch(error){$('#results').innerHTML='<div class="empty-result"><strong>Database could not load</strong><p>Refresh this page when connected. No dosing result is available.</p><button onclick="location.reload()">Retry</button></div>';$('#result-count').textContent='Unavailable';$('#monograph').innerHTML='<div class="no-selection"><h2>Reference unavailable</h2><p>Do not rely on an incomplete page. Check a current approved source.</p></div>';$('#search').disabled=true;}
}
$('#search').addEventListener('input',()=>{listLimit=60;if(db)renderResults();});
for(const id of ['route-filter','content-filter','otc-filter','setting-filter'])$('#'+id).addEventListener('change',()=>{listLimit=60;if($('#setting-filter').value!=='all')mode=$('#setting-filter').value;renderResults();});
$('#more-results').addEventListener('click',()=>{listLimit+=60;renderResults();});
$('#clear-search').addEventListener('click',()=>{$('#search').value='';renderResults();$('#search').focus();});
$('#mobile-category').addEventListener('change',e=>{view=['saved','new'].includes(e.target.value)?e.target.value:'all';category=['saved','new'].includes(e.target.value)?'all':e.target.value;renderResults();});
document.addEventListener('click',e=>{
 const drug=e.target.closest('[data-drug]');if(drug){selected=drug.dataset.drug;renderResults();if(innerWidth<761)openSelected();return;}
 const tab=e.target.closest('[data-mode]');if(tab){mode=tab.dataset.mode;renderMonograph();$(`#tab-${mode}`).focus({preventScroll:true});return;}
 const q=e.target.closest('[data-query]');if(q){resetFilters();$('#search').value=q.dataset.query;renderResults();return;}
 const cat=e.target.closest('[data-category]');if(cat){category=cat.dataset.category;view='all';renderResults();return;}
 const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;category='all';renderResults();return;}
 if(e.target.closest('#clear-filters')||e.target.closest('#show-filtered-match')){resetFilters();renderResults();return;}
 if(e.target.closest('#reset-filters')){$('#search').value='';resetFilters();renderResults();return;}
 if(e.target.closest('#save-drug')){const removing=favourites.has(selected);removing?favourites.delete(selected):favourites.add(selected);const persisted=storageSet('renalrounds-favourites',JSON.stringify([...favourites]));renderResults();notify(`${removing?'Removed from':'Added to'} favourites${persisted?'':' (this session only)'}`);return;}
 if(e.target.closest('[data-open="about"]')){$('#about').showModal();return;}
});
$('#close-about').addEventListener('click',()=>$('#about').close());
$('#about').addEventListener('click',e=>{if(e.target===$('#about')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#font-toggle').addEventListener('click',()=>{applyTextSize(readerLevel+1);saveTextSize();});
$('#font-decrease').addEventListener('click',()=>{applyTextSize(readerLevel-1);saveTextSize();});
$('#font-reset').addEventListener('click',()=>{applyTextSize(0);saveTextSize();});
$('#export').addEventListener('click',()=>{if(db)exportDatabase();});
document.addEventListener('keydown',e=>{
 if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#about').open&&!$('#completion').open&&!$('#references').open&&!$('#calculator').open){e.preventDefault();$('#search').focus();}
 if(e.key==='Escape'&&document.activeElement===$('#search')){$('#search').value='';if(db)renderResults();}
 if(e.key==='ArrowDown'&&document.activeElement===$('#search')){e.preventDefault();$('#results button')?.focus();}
 const result=document.activeElement.closest('[data-drug]');if(result&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const buttons=[...document.querySelectorAll('[data-drug]')],i=buttons.indexOf(result),next=i+(e.key==='ArrowDown'?1:-1);buttons[next]?.focus();}
 const tab=document.activeElement.closest('[data-mode]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const keys=Object.keys(modeNames),i=keys.indexOf(mode);mode=e.key==='Home'?keys[0]:e.key==='End'?keys.at(-1):keys[(i+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length];renderMonograph();$(`#tab-${mode}`).focus({preventScroll:true});}
});
window.addEventListener('hashchange',()=>{if(!db)return;const p=new URLSearchParams(location.hash.slice(1));if(db.drugs.some(d=>d.id===p.get('drug'))){selected=p.get('drug');resetFilters();$('#search').value='';}if(Object.hasOwn(modeNames,p.get('mode')))mode=p.get('mode');renderResults();});
function renderSuggestions(){const matches=suggestions($('#search').value);return matches.length?`<p>Possible spelling matches — select to open:</p><div class="spelling-options">${matches.map(d=>`<button data-suggestion="${h(d.name)}">${h(d.name)}</button>`).join('')}</div>`:'';}
